import{_ as i,o as r,c as l,j as e,a as n,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/unterricht-kataloge/kataloge-teilleistungsarten-01.png",o="/bilder/unterricht-kataloge/kataloge-teilleistungsarten-02.png",k=JSON.parse('{"title":"Teilleistungsarten im Katalog anlegen","description":"","frontmatter":{"title":"Teilleistungsarten im Katalog anlegen","source_pageid":312,"source_revision":5447},"headers":[],"relativePath":"schild3/unterricht-kataloge/teilleistungs-arten-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/teilleistungs-arten-schulbezogene-kataloge.md"}'),g={name:"schild3/unterricht-kataloge/teilleistungs-arten-schulbezogene-kataloge.md"};function u(d,t,c,h,p,b){return r(),l("div",null,[...t[0]||(t[0]=[e("h1",{id:"teilleistungsarten-im-katalog-anlegen",tabindex:"-1"},[n("Teilleistungsarten im Katalog anlegen "),e("a",{class:"header-anchor",href:"#teilleistungsarten-im-katalog-anlegen","aria-label":'Permalink to "Teilleistungsarten im Katalog anlegen"'},"​")],-1),e("p",null,"Definieren Sie die an Ihrer Schule verwendeten Arten von Einzel- und Zwischenleistungen. Diese können anschließend Fächern und Leistungsdaten zugeordnet werden.",-1),e("p",null,[e("strong",null,"Teilleistungen"),n(" dienen zur Erfassung aller Leistungen von Schülerinnen und Schülern, die keine Zeugnisnoten sind, die aber entweder mit dauerhaft erfasst werden sollen oder die zur Weiterarbeit in anderen Prozessen nützlich sind.")],-1),e("p",null,[n("Die "),e("strong",null,"Teilleistungsarten"),n(" können dabei individuell festgelegt werden.")],-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Beispiele für Teilleistungen sind einzelne Klassenarbeiten, sonstige Leistungen, Projektarbeiten oder Prüfungsnoten. In der gymnasialen Oberstufe können Sie damit schriftliche Leistungen und sonstige Mitarbeit getrennt erfassen. Auch Zwischenstände für Elternsprechtage und Vornoten vor Prüfungen lassen sich so festhalten.")],-1),a('<p>Übersichten der Teilleistungen können durch einen Report ausgegeben werden und so als Grundlage für zum Beispiel pädagogische Konferenzen dienen.</p><p>Nach Festlegung der an der Schule verwendeten Teilleistungsarten in diesem Programmfenster müssen die jeweiligen Teilleistungsarten den entsprechenden Jahrgängen, Klassen oder Schülergruppen durch einen <em>Gruppenprozess</em> zugewiesen werden, bevor Noten eingetragen werden können.</p><h2 id="anlegen-neuer-teilleistungsarten" tabindex="-1">Anlegen neuer Teilleistungsarten <a class="header-anchor" href="#anlegen-neuer-teilleistungsarten" aria-label="Permalink to &quot;Anlegen neuer Teilleistungsarten&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-teilleistungsarten-01.png"><img src="'+s+'" alt="Übersicht über das Fenster Kataloge ➜ Teilleistungs-Arten." loading="lazy"></a></p><p><em>Übersicht über das Fenster Kataloge ➜ Teilleistungs-Arten.</em></p><p>Durch Klick auf das <code>+</code> kann eine neue Teilleistungsart angelegt werden.</p><p>In der Spalte &#39;<em>Teilleistungsart</em> wird die entsprechende Bezeichnung eingetragen.</p><p>Die Einträge in der Spalte <strong>Sortierung</strong> sollten nicht manuell verändert werden, da es sonst zu ungewünschten bzw. unerwarteten Sortierungen kommt.</p><p>Eine individuelle Sortierung wird im nächsten Abschnitt erläutert.</p><h2 id="sortierung-der-teilleistungsarten" tabindex="-1">Sortierung der Teilleistungsarten <a class="header-anchor" href="#sortierung-der-teilleistungsarten" aria-label="Permalink to &quot;Sortierung der Teilleistungsarten&quot;">​</a></h2><p>Bei Verwendung der <strong>Sortierung</strong> &quot;Teilleistungsart&quot; sortiert das Programm alphabetisch, wobei alle Großbuchstaben vor den Kleinbuchstaben einsortiert werden.</p><p>In dieser Reihenfolge werden die Teilleistungen auch in den entsprechenden Reports sortiert.</p><p><a href="/bilder/unterricht-kataloge/kataloge-teilleistungsarten-02.png"><img src="'+o+'" alt="Individuelle Sortierung der Teilleistungsarten." loading="lazy"></a></p><p><em>Individuelle Sortierung der Teilleistungsarten.</em></p><p>Ist eine <strong>individuelle Sortierung</strong> gewünscht, so kann dies eingestellt werden.</p><p>Die Pfeile am linken Rand werden damit aktiviert und erlauben eine individuelle Reihenfolge, die so auch in Reports abgerufen werden kann.</p><p>Im Screenshot dargestellt ist die Verschiebung der neu angelegten Teilleistungsart &quot;KA 2&quot; (&quot;Klassenarbeit 2&quot;).</p><h2 id="bearbeiten-von-teilleistungsarten" tabindex="-1">Bearbeiten von Teilleistungsarten <a class="header-anchor" href="#bearbeiten-von-teilleistungsarten" aria-label="Permalink to &quot;Bearbeiten von Teilleistungsarten&quot;">​</a></h2><p>Durch einen Doppelklick in das entsprechende Feld in der Spalte &quot;Teilleistungsart&quot; kann die Bezeichnung bereits angelegter Teilleistungsarten geändert werden.</p><p>Ein Klick auf das <code>-</code> löscht die angelegte Teilleistungsart nach Bestätigung einer Dialogabfrage.</p><h2 id="export-in-eine-excel-tabelle" tabindex="-1">Export in eine Excel-Tabelle <a class="header-anchor" href="#export-in-eine-excel-tabelle" aria-label="Permalink to &quot;Export in eine Excel-Tabelle&quot;">​</a></h2><p>Durch Klick auf <strong>Excel-Export</strong> und <code>Speichern</code> im folgenden Fenster kann die aktuelle Ansicht in eine Excel-Tabelle exportiert werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Teilleistungs-Arten_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5447.</p>',24)])])}const f=i(g,[["render",u]]);export{k as __pageData,f as default};
